<script lang="ts">
 import {ScanEye} from 'lucide-svelte';
 export type CalendarSource={id:string;kind?:'person'|'group';name?:string;owner?:{name?:string;address?:string};isSharedWithMe?:boolean;isDefaultCalendar?:boolean};
 const tone=(id:string)=>id==='primary'?'var(--accent)':`var(--calendar-color-${Array.from(id).reduce((n,c)=>n+c.charCodeAt(0),0)%3+1})`;
 let {sources,enabled,focusId,busy,error,next,onToggle,onFocus,onRefresh,onMore,onRemove=()=>{},locked=false}:{sources:CalendarSource[];enabled:string[];focusId:string|null;busy:boolean;error:string;next:string|null;onToggle:(id:string)=>void;onFocus:(id:string)=>void;onRefresh:()=>void;onMore:()=>void;onRemove?:(id:string)=>void;locked?:boolean}=$props();
</script>
<section class="calendar-picker" aria-label="Calendar visibility"><header><strong>Calendars</strong><button disabled={busy||locked} onclick={onRefresh}>Refresh list</button></header>
 {#each [{label:'MINE',items:[{id:'primary',name:'My calendar',owner:{name:'You'}}]},{label:'SHARED WITH ME',items:sources.filter(s=>s.isSharedWithMe===true&&s.kind!=='group')},{label:'TEAMS CALENDARS',items:sources.filter(s=>s.kind==='group')},{label:'OTHER CALENDARS',items:sources.filter(s=>s.isSharedWithMe!==true&&s.kind!=='group')}] as group}
 {#if group.items.length}<p class="group-label">{group.label}</p>{#each group.items as source(source.id)}<div class="calendar-source" style:--calendar-color={tone(source.id)}><strong>{source.name||'Calendar'}</strong><small>{source.id==='primary'?'Your calendar':`${source.owner?.name||source.owner?.address||'Owner unavailable'} · View only in TAUT`}</small><div class="source-controls"><label class="visibility"><input type="checkbox" role="switch" aria-label={`Show ${source.name||'calendar'} in My view`} checked={enabled.includes(source.id)} disabled={locked||!!focusId||!enabled.includes(source.id)&&enabled.length>=12} onchange={()=>onToggle(source.id)}/><span class="track" aria-hidden="true"></span><span>{enabled.includes(source.id)?'In my view':'Hidden'}</span></label><button aria-label={`Focus on ${source.name||'calendar'}`} aria-pressed={focusId===source.id} disabled={locked} onclick={()=>onFocus(source.id)}><ScanEye size={14}/>{focusId===source.id?'Focused':'Focus'}</button></div>{#if source.id.startsWith("person:")}<button class="remove" disabled={locked||!!focusId} onclick={()=>onRemove(source.id)} aria-label={`Remove ${source.name} calendar from TAUT`}>Remove from TAUT</button>{/if}</div>{/each}{/if}{/each}
 {#if busy}<p class="picker-note" role="status">Finding calendars…</p>{/if}{#if error}<p class="picker-note" role="status">{error}</p>{/if}{#if next}<button disabled={busy||locked} onclick={onMore}>Load more calendars</button>{/if}
 <p class="picker-note">{focusId?'My view is saved. Return to change visibility.':'Switches build My view. Focus is temporary.'}<br/>Up to 12 visible calendars. Reminders use your primary calendar.</p>
 <details><summary>Missing a shared calendar?</summary><p>Only calendars returned by Microsoft for this mailbox appear here. Accept or add shared calendars in Outlook first. Use Add a person’s calendar for a coworker. Teams calendars come from your joined Teams; other accounts and non-Teams groups are not included yet.</p></details>
</section>
